using CombatSolver.Engine.Common;
using MegaCrit.Sts2.Core.Entities.Cards;

namespace CombatSolver.Engine.InCombat.Simulation;

internal sealed partial class CombatPredictionSimulator
{
    private string ResearchManualCaptureReason(PredictedCard card, CardPlay play)
    {
        if (_capturedManualCardChoice != null) return "already_captured";
        if (!SupportsManualCardChoiceContinuation(card.Preview)) return "unsupported_card";
        if (play.IsAutoPlay) return "autoplay";
        if (play.PlayCount != 1 || play.PlayIndex != 0) return $"replay_{play.PlayCount}_{play.PlayIndex}";
        if (CurrentFrame is not { Parent: null } trace) return "nested_trace";
        if (_damageSource != null) return "active_damage";
        if (_activeDrawDepth != 0) return "active_draw";
        if (ActionRelicTriggers != null) return "relic_recorder";
        if (_blockGainedByCardPlay.Count > (_blockGainedByCardPlay.ContainsKey(play) ? 1 : 0)) return "other_block_transaction";
        if (!StateStore.SupportsManualCardChoiceContinuation) return "state_store";
        if (State.CombatState is not ICombatPredictionCardContinuationState { CanCaptureManualCardChoice: true })
            return "combat_transaction";
        return History.ResearchManualHistoryReason(_manualChoiceHistoryStart, trace, play);
    }
}

internal sealed partial class CombatPredictionHistory
{
    internal string ResearchManualHistoryReason(int start, PredictionTraceFrame action, CardPlay play)
    {
        if (_pendingDeferredEntries != 0) return "history_deferred";
        if ((_prefix?.Count ?? 0) != start) return "history_prefix";
        if (_tail is null) return "history_no_tail";
        int starts = 0;
        foreach (var entry in _tail)
        {
            if (entry is CombatPredictionCardPlayStartedEntry started)
            {
                if (!ReferenceEquals(started.CardPlay, play) || !ReferenceEquals(entry.Trace, action))
                    return "history_other_play";
                starts++;
            }
            else if (entry is not (CombatPredictionRiskEntry or CombatPredictionDamageReceivedEntry
                or CombatPredictionCreatureAttackedEntry or CombatPredictionCardDrawnEntry
                or CombatPredictionCardDrawResolvedEntry or CombatPredictionCardsSelectedEntry
                or CombatPredictionCardCostsRandomizedEntry or CombatPredictionCardGenerationOptionsEntry
                or CombatPredictionCardGeneratedEntry or CombatPredictionCardGenerationResolvedEntry))
                return "history_entry_" + entry.GetType().Name;
            if (entry.Trace is null) return "history_no_trace";
            bool foundRoot = false;
            foreach (var trace in entry.Trace.Ancestors())
            {
                if (!ReferenceEquals(trace.Source, action.Source)) return "history_source_" + trace.Source.GetType().Name;
                if (ReferenceEquals(trace, action)) foundRoot = true;
            }
            if (!foundRoot) return "history_other_root";
        }
        return starts == 1 ? "accepted" : "history_start_count_" + starts;
    }
}

using System.Collections.Concurrent;
using System.Diagnostics;
using System.Text.Json;
using CombatSolver.Engine.InCombat.Simulation;
using CombatSolver.Engine.Common;
