namespace CombatSolver;
internal static class TaskStablePotionPrefixAudit
{
    private sealed class Counts { internal long Visits, SourceSafe, Closed, Witness, CouldCut, Width, Ticks; }
    private static readonly ConcurrentDictionary<string, Counts> Items = new();
    internal static void Record(string key, bool safe, bool closed, bool witness, bool cut, int width, long ticks)
    {
        var c = Items.GetOrAdd(key, _ => new()); Interlocked.Increment(ref c.Visits);
        if(safe) Interlocked.Increment(ref c.SourceSafe); if(closed) Interlocked.Increment(ref c.Closed);
        if(witness) Interlocked.Increment(ref c.Witness); if(cut) { Interlocked.Increment(ref c.CouldCut); Interlocked.Add(ref c.Width,width); }
        Interlocked.Add(ref c.Ticks,ticks);
    }
    internal static string Snapshot() => JsonSerializer.Serialize(Items.OrderBy(p=>p.Key).Select(p=>new {
        key=p.Key, visits=p.Value.Visits, sourceSafe=p.Value.SourceSafe, closed=p.Value.Closed,
        witness=p.Value.Witness, couldCut=p.Value.CouldCut, rawOptionCountUnderCut=p.Value.Width,
        queryWallMs=p.Value.Ticks*1000.0/Stopwatch.Frequency }).ToArray());
}
internal static partial class StrategicHpRecoveryBound
{
    internal static bool ResearchCertifiedChoiceSources(CardChoiceSpec spec)
        => spec.Options.Concat(spec.SourceCards).All(card => ComponentRemainingCard(card.Preview, useReviewedSources:true));
}
internal sealed partial class CombatBeamSolver
{
    private void ObserveStablePotionPrefixForResearch(SimulationSnapshot? snapshot, CardChoiceSpec spec, string potionId)
    {
        long started=Stopwatch.GetTimestamp(); bool safe=false, closed=false, witness=false, cut=false;
        if (snapshot is { HasSimulator:true, HasRisk:false, BoundaryReason:SearchBoundaryReason.None }
            && !snapshot.PlayerDead && !snapshot.AllEnemiesDead
            && root.UsesPruningComponentHealingCertificate && policy.EffectiveGrowthBudgets==default
            && policy.RelicTargets.Count==0 && _theftPolicy!=SolverTheftPolicy.PreserveResources
            && !_potionStrategy.HasForcedDirectives && snapshot.OutstandingStolenResource==0
            && StrategicHpRecoveryBound.ResearchCertifiedChoiceSources(spec))
        {
            int healing=StrategicHpRecoveryBound.ComponentHealingUpperBound(
                (CombatPredictionSimulator)snapshot.Simulator,_player,
                root.PostCombatRelicHeal.UnconditionalHeal+root.PostCombatRelicHeal.WoundedHeal,
                includePotionHealing:!_forceAllPotionsDisabled,maximumExplicitPotionUses:_maximumPotionUses,
                potionStrategy:_potionStrategy,effectivePotionPolicy:_potionPolicy,useReviewedSources:true);
            safe=healing!=int.MaxValue;
            int uses=PotionUsePolicy.ExplicitUseCount(snapshot.PotionUseCount,snapshot.AutomaticPotionUseCount);
            closed=CanUseSharedPotionTier(uses,_maximumPotionUses,_forceAllPotionsDisabled,_potionPolicy,_potionStrategy.HasForcedDirectives);
            if(safe && closed && _useSharedPrimaryIncumbents && uses>=_minimumPotionUses)
            {
                witness=_primaryIncumbents.TryGetStrictHpWitness(0,uses,snapshot.ExplicitPotionStrategicCost,out var incumbent);
                cut=witness && StrategicHpLowerBound(snapshot,_strategicBossHpRelief,healing)>incumbent.StrategicHpDeficit;
            }
        }
        string key=potionId+":"+(_directSearchPurpose?.ToString()??_attributionPurpose?.ToString()??"unspecified");
        TaskStablePotionPrefixAudit.Record(key,safe,closed,witness,cut,spec.Options.Count,Stopwatch.GetTimestamp()-started);
    }
}

internal static partial class StrategicHpRecoveryBound
{
    internal static int ResearchOwnedManualHealingUpperBound(
        CombatPredictionSimulator simulator, Player player, int postCombatHeal,
        bool includePotionHealing = true, int? maximumExplicitPotionUses = null,
        PotionStrategySnapshot? potionStrategy = null,
        SolverPotionPolicy effectivePotionPolicy = SolverPotionPolicy.Smart,
        bool useReviewedSources = false)
    {
        if (simulator.HasPendingChoice)
        {
            var frame = typeof(CombatPredictionSimulator).GetField("_ownedManualCardChoice",
                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)!.GetValue(simulator)
                as ManualCardChoiceFrame;
            var pending = ((SimulatedCombatState)simulator.State.CombatState).PendingTurnStartChoice;
            if (frame is null || frame.Trace.Parent is not null || frame.Play.IsAutoPlay
                || frame.Play.PlayCount != 1 || frame.Play.PlayIndex != 0
                || !ComponentRemainingCard(frame.Card.Preview, useReviewedSources)
                || pending is not { SourceId: "", Effect: not PlanChoiceEffect.ModDefined, Spec: not null }
                || pending.Spec.Options.Concat(pending.Spec.SourceCards)
                    .Any(card => !ComponentRemainingCard(card.Preview, useReviewedSources)))
                return int.MaxValue;
        }
        SimulatedCombatState combat = (SimulatedCombatState)simulator.State.CombatState;
        var state = simulator.State.GetPlayerCombatState(player);
        if (combat.KnownEnemies.Count == 0
            || combat.KnownEnemies.Any(enemy => enemy.Monster is null
                || !ComponentEnemy(enemy.Monster.GetType(), useReviewedSources))
            || combat.RelicsOf(player).Any(relic => !ComponentRelic(relic.GetType(), useReviewedSources))
            || state.AllCards.Any(card => !ComponentRemainingCard(card.Preview, useReviewedSources))
            || combat.PendingReturningCards.Any(card => !ComponentRemainingCard(card.Preview, useReviewedSources))
            || combat.Allies.Any(ally => ally.Player is null && (ally.Monster?.GetType() != typeof(Osty)
                || useReviewedSources && !ReferenceEquals(ally.PetOwner, player)))
            || state.OrbQueue.Orbs.Any(orb => orb.GetType() != typeof(LightningOrb)
                && orb.GetType() != typeof(FrostOrb) && orb.GetType() != typeof(DarkOrb)
                && orb.GetType() != typeof(PlasmaOrb) && orb.GetType() != typeof(GlassOrb)))
            return int.MaxValue;
        long regen = 0;
        foreach (PowerModel power in combat.EffectivePowers())
        {
            Type type = power.GetType();
            if (!ComponentPower(type, useReviewedSources))
                return int.MaxValue;
            if (useReviewedSources && (type == typeof(SpeedPotionPower)
                    && !ReferenceEquals(power.Owner, player.Creature)
                || type == typeof(ShacklingPotionPower) && !combat.KnownEnemies.Contains(power.Owner)
                || type == typeof(SandpitPower) && (!combat.KnownEnemies.Contains(power.Owner)
                    || power.Owner.Monster?.GetType() != typeof(TheInsatiable)
                    || !ReferenceEquals(power.Target, player.Creature))))
                return int.MaxValue;
            if (type == typeof(RegenPower) && ReferenceEquals(power.Owner, player.Creature))
                regen += Math.Max(0, power.Amount);
            if (type == typeof(ReattachPower) && (power.Owner.Player is not null
                || !combat.KnownEnemies.Contains(power.Owner)
                || power.Owner.Monster?.GetType() != typeof(DecimillipedeSegmentFront)
                    && power.Owner.Monster?.GetType() != typeof(DecimillipedeSegmentMiddle)
                    && power.Owner.Monster?.GetType() != typeof(DecimillipedeSegmentBack)))
                return int.MaxValue;
        }
        if (maximumExplicitPotionUses is { } maximum
            && combat.PotionUses.Count(static use => !use.Automatic) >= maximum)
            includePotionHealing = false;
        int slots = ((ICombatPredictionPlayerLimits)combat).GetPotionSlotCount(player);
        for (int slot = 0; slot < slots; slot++)
        {
            PotionModel? potion = combat.GetPotionAtSlot(player, slot);
            if (potion is null || !combat.IsPotionAvailable(player, slot))
                continue;
            if (!ComponentPotion(potion.GetType()))
                return int.MaxValue;
            // Existing Regen is retained even when manual potion use is forbidden.
            // Summing all legally available doses before the first tick overestimates
            // every staggered sequence, including a smaller remaining use allowance.
            if (includePotionHealing && potion.GetType() == typeof(RegenPotion)
                && (potionStrategy is null || potionStrategy.AllowsExplicitUse(
                    slot, potion.Id.Entry, effectivePotionPolicy, forceAllDisabled: false)))
                regen += Math.Max(0, potion.DynamicVars["RegenPower"].IntValue);
        }
        return RegenerationHealingUpperBound(regen, postCombatHeal);
    }
}

